// Code playground: Risiko transaksi berdasarkan indikator sederhana (edukasi, bukan fatwa)
function riskScore(input){
  let score = 0;
  if(input.adaBunga) score += 40; // indikasi riba
  if(!input.deskripsiJelas) score += 35; // indikasi gharar
  if(input.adaSpekulasi) score += 25; // indikasi maisir
  return score;
}

function verdict(score){
  if(score >= 60) return 'Tinggi: perlu ditinjau ulang (hindari keputusan cepat)';
  if(score >= 30) return 'Sedang: cek lagi info/akad dengan lebih teliti';
  return 'Rendah: indikator utama relatif aman (tetap cek akad & kejujuran)';
}

const input = { adaBunga: false, deskripsiJelas: true, adaSpekulasi: false };
const score = riskScore(input);
console.log('Input:', input);
console.log('Skor risiko:', score);
console.log('Status:', verdict(score));

// Code playground: Draft akad sederhana (edukasi)
function createAkad({produk, harga, estimasiKirim, kondisi, caraPembayaran}){
  const lines = [];
  lines.push('AKAD MUAMALAH DIGITAL');
  lines.push('Produk: ' + produk);
  lines.push('Kondisi: ' + kondisi);
  lines.push('Harga: ' + harga);
  lines.push('Estimasi kirim: ' + estimasiKirim);
  lines.push('Cara pembayaran: ' + caraPembayaran);
  lines.push('Prinsip: kejujuran dan keterbukaan');
  lines.push('Ridha: pihak penjual dan pembeli setuju tanpa paksaan');
  lines.push('Kesimpulan: transaksi dilakukan sesuai kesepakatan di atas');
  return lines.join(' | ');
}

const draft = createAkad({
  produk: 'Sepatu lari',
  harga: 'Rp250.000',
  estimasiKirim: '1-2 hari kerja',
  kondisi: 'Baru, sesuai foto',
  caraPembayaran: 'Transfer/VA sesuai marketplace'
});

console.log(draft);
